#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    int n = s.size();
    int m = t.size();

    vector<int> left(m), right(m);

    for (int i = 0, j = 0; i < n && j < m; ++i) {
        if (s[i] == t[j]) left[j++] = i;
    }

    for (int i = n - 1, j = m - 1; i >= 0 && j >= 0; --i) {
        if (s[i] == t[j]) right[j--] = i;
    }

    int answer = max(right[0], n - left[m - 1] - 1);

    for (int i = 0; i + 1 < m; ++i) {
        answer = max(answer, right[i + 1] - left[i] - 1);
    }

    cout << answer << '\n';
    return 0;
}

